# Corrige el encoding de los 4 archivos del feature de SharePoint en Ubicaciones.
# Esta version escribe los archivos a partir de Base64 (puro ASCII), para que no
# dependa de como PowerShell interprete acentos/enies -- evita el problema anterior.
# Ejecuta esto parado en la raiz del repo.

$ErrorActionPreference = 'Stop'

# --- backend/src/sharepointUbicaciones.js ---
$f1b64 = ""
$dir = Split-Path -Parent "backend\src\sharepointUbicaciones.js"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\backend\src\sharepointUbicaciones.js", [System.Convert]::FromBase64String($f1b64))

# --- backend/src/routes/arrendamientos/documentos.js ---
$f2b64 = ""
$dir = Split-Path -Parent "backend\src\routes\arrendamientos\documentos.js"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\backend\src\routes\arrendamientos\documentos.js", [System.Convert]::FromBase64String($f2b64))

# --- backend/src/routes/arrendamientos/locations.js ---
$f3b64 = ""
$dir = Split-Path -Parent "backend\src\routes\arrendamientos\locations.js"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\backend\src\routes\arrendamientos\locations.js", [System.Convert]::FromBase64String($f3b64))

# --- frontend/src/pages/arrendamientos/LocationDetalle.jsx ---
$f4b64 = ""
$dir = Split-Path -Parent "frontend\src\pages\arrendamientos\LocationDetalle.jsx"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\frontend\src\pages\arrendamientos\LocationDetalle.jsx", [System.Convert]::FromBase64String($f4b64))

Write-Host "Listo: 4 archivos re-escritos con encoding correcto (via Base64)."
git add backend/src/sharepointUbicaciones.js backend/src/routes/arrendamientos/documentos.js backend/src/routes/arrendamientos/locations.js frontend/src/pages/arrendamientos/LocationDetalle.jsx
git commit -m "Corregir encoding (acentos/enies) de los archivos de SharePoint en Ubicaciones"
git push origin main